      size_offset += WriteBlob(image, compressed_length, compact_pixels);
    } else {
      written_bytes += image->columns;
      size_offset += WriteBlob(image, image->columns, pixels);
    }

    pixels = (Quantum *) RelinquishMagickMemory(pixels);
  }

  return written_bytes;
}

