size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info,
                       Image *image, Image *next_image, QuantumType quantum_type,
                       unsigned char *compact_pixels, MagickOffsetType size_offset,
                       MagickBooleanType separate) {
  size_t bytes_written = 0;
  size_t width = image->columns;
  size_t height = image->rows;
  unsigned char *pixels = NULL;
  size_t row = 0;
  size_t row_size = width * sizeof(Quantum);
  unsigned char *export_pixels = NULL;

  if (image->storage_class == PseudoClass && (image->colors == 1))
    (void) SetImageColor(image, &image->colormap[0]);

  for (row = 0; row < height; row++) {
    export_pixels = (unsigned char *) AcquireQuantumInfoBuffer(image, quantum_type, width);
    GetPixelInfo(image_info, &image->exception, quantum_type);
    ExportPixels(image, 0, row, width, 1, quantum_type, export_pixels, &image->exception);

    if (psd_info->compression == RLECompression) {
      size_t compressed_size = CompressRLE(export_pixels, width, height, &pixels, &image->exception);
      WriteBlobMemory(image, compressed_size, pixels);
      bytes_written += compressed_size;
    }
    else if (psd_info->compression == ZipCompression) {
      size_t compressed_size = CompressZIP(export_pixels, width, height, &pixels, &image->exception);
      WriteBlobMemory(image, compressed_size, pixels);
      bytes_written += compressed_size;
    }
    else {
      WriteBlobMemory(image, row_size, export_pixels);
      bytes_written += row_size;
    }

    if (export_pixels)
      export_pixels = (unsigned char *) RelinquishMagickMemory(export_pixels);
  }

  if (separate && next_image)
    WritePSDChannel(psd_info, image_info, next_image, NULL, quantum_type, compact_pixels, size_offset + bytes_written, MagickFalse);

  return bytes_written;
}
